<style>
.atlas-inscripciones{--ai-primary:#163b70;--ai-dark:#102d56;--ai-border:#e2e9f2;--ai-muted:#718096;color:#24364d;font-size:14px}
.atlas-inscripciones *{box-sizing:border-box}.atlas-inscripciones h2{font-size:24px;color:var(--ai-dark);margin:0 0 7px;font-weight:750}.atlas-inscripciones p{line-height:1.5}.ai-header{display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap;margin-bottom:22px}.ai-muted{color:var(--ai-muted)}
.ai-card{background:#fff;border:1px solid var(--ai-border);border-radius:13px;box-shadow:0 3px 16px rgba(24,49,85,.045);margin-bottom:22px;overflow:hidden}.ai-card-head{padding:16px 20px;background:#f9fbfe;border-bottom:1px solid var(--ai-border);display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.ai-card-body{padding:20px}.ai-count{margin-left:auto;color:var(--ai-muted);font-weight:400}
.ai-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:22px}.ai-stat{padding:19px;background:#fff;border:1px solid var(--ai-border);border-radius:12px;color:var(--ai-muted);font-size:13px}.ai-stat strong{display:block;margin-top:8px;color:var(--ai-primary);font-size:29px}
.ai-filters{display:grid;grid-template-columns:minmax(180px,2fr) repeat(4,minmax(125px,1fr));gap:13px;align-items:end}.ai-field{display:flex;flex-direction:column;gap:7px;min-width:0}.ai-field label{font-size:12px;font-weight:700;color:#344861}.ai-field input,.ai-field select,.ai-field textarea{width:100%;min-height:41px;border:1px solid #d6dfeb;border-radius:8px;padding:9px 11px;background:#fff;color:#24364d;font:inherit}.ai-field textarea{min-height:95px;resize:vertical}.ai-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:15px}.ai-btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-height:36px;padding:8px 12px;border:1px solid #d4dfed;border-radius:8px;background:#fff;color:var(--ai-primary);font-size:12px;font-weight:700;text-decoration:none;cursor:pointer}.ai-btn.primary{background:var(--ai-primary);border-color:var(--ai-primary);color:#fff}.ai-btn.danger{border-color:#f2c9c9;color:#a62626;background:#fff8f8}.ai-btn:disabled{opacity:.55;cursor:not-allowed}
.ai-table-wrap{overflow-x:auto}.ai-table{border-collapse:collapse;width:100%;font-size:13px}.ai-table th{text-align:left;background:#f5f8fc;padding:13px 15px;color:#4d6078;white-space:nowrap;border-bottom:1px solid var(--ai-border)}.ai-table td{padding:13px 15px;border-bottom:1px solid #edf1f6;vertical-align:middle}.ai-table tr:last-child td{border-bottom:0}.ai-table tbody tr:hover{background:#f9fbfe}.ai-empty{text-align:center;color:var(--ai-muted);padding:26px!important}.ai-tag{display:inline-block;padding:5px 10px;border-radius:20px;background:#e6f6ed;color:#167046;font-size:11px;font-weight:700}.ai-tag.off{background:#eef1f5;color:#657284}.ai-footer{padding:15px 20px;border-top:1px solid var(--ai-border)}.ai-notice{padding:13px 16px;border-radius:9px;background:#eaf5ee;color:#17613a;margin-bottom:16px}.ai-notice.error{background:#fff0ef;color:#a12d26}.ai-detail{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.ai-detail dl{display:grid;grid-template-columns:40% 60%;margin:0}.ai-detail dt,.ai-detail dd{padding:10px 5px;border-bottom:1px solid #edf1f6;margin:0;overflow-wrap:anywhere}.ai-detail dt{color:var(--ai-muted);font-size:12px}.ai-detail dd{font-weight:600}.ai-wide{grid-column:1/-1}
.ai-overlay[hidden]{display:none!important}.ai-overlay{position:fixed;inset:0;z-index:1200;background:rgba(8,22,45,.62);display:flex;align-items:center;justify-content:center;padding:20px}.ai-modal{background:#fff;border-radius:14px;width:min(100%,550px);box-shadow:0 18px 55px rgba(0,0,0,.2);max-height:90vh;overflow:auto}.ai-modal-head{display:flex;justify-content:space-between;align-items:center;padding:19px 22px;border-bottom:1px solid var(--ai-border)}.ai-modal-head h3{margin:0;color:var(--ai-dark);font-size:18px}.ai-modal-body{padding:22px}.ai-modal-foot{display:flex;justify-content:flex-end;gap:9px;padding:16px 22px;border-top:1px solid var(--ai-border)}
@media(max-width:1100px){.ai-filters{grid-template-columns:repeat(3,minmax(0,1fr))}.ai-stats{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:720px){.ai-filters,.ai-detail{grid-template-columns:1fr}.ai-stats{grid-template-columns:1fr 1fr}}@media(max-width:480px){.ai-stats{grid-template-columns:1fr}}
</style>
